    publishTaskPullRequest: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                taskId: components["parameters"]["TaskId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description One line, and required: `gh pr create` opens an editor without one, and the machine has none. At most 256 characters, counted the way GitHub counts them, so a title written in Chinese is not refused for its length in bytes. A control character in it is a 400. */
                    title?: string;
                    /** @description Markdown, at most 32 KiB. Newlines are its substance and are not refused. The bound is the query frame's rather than GitHub's: these words travel inside one, where a byte can cost six once encoded, so a larger body would be accepted here and then refused by the frame with a sentence naming no field. */
                    body?: string;
                };
            };
        };
        responses: {
            /** @description What the publish did, including a refusal: a blocked publish is an outcome of a question the caller asked, so it is answered rather than failed. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["PublishReport"];
                };
            };
            /** @description The words cannot travel, or the machine refused the push. Both are the same answer because both are the same kind of news: nothing was published, and the reason is in the body. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The caller is neither the node's holder nor a device paired to it */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description No such task */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description This session runs on this daemon, so there is no other machine to ask, or the workspace it runs in is on that machine and this Hub cannot place it. The body carries a code — "session_runs_here" for the first — because the console draws its own sentence for that one and must not draw it for the other. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The machine published something the Hub could not write down */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description GitHub integration is not configured */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
